/**
 * Window features for the false-positive verifier.
 * Line-for-line port of ml/guardian_ml/features.py (the canonical definition) — keep in sync;
 * tests/fpVerifier.test.js checks parity against fixtures generated by the Python trainer.
 */

const WINDOW = 30;
const MIN_TICKS = 10;

const FEATURE_NAMES = [
  'n_ticks',
  'ear_rel_last',
  'ear_rel_mean',
  'ear_rel_min',
  'ear_rel_std',
  'ear_rel_slope',
  'ear_rel_mad',
  'frac_below',
  'run_below_now',
  'longest_run_below',
  'missing_ear_frac',
  'perclos_rel_last',
  'perclos_rel_slope',
  'hr_present_frac',
  'hr_mean',
  'hr_slope',
  'face_conf_mean',
  'face_conf_min',
  'fusion_last',
  'fusion_mean',
  'frac_nonalert',
  'frac_drowsy',
];

const valid = (v) => typeof v === 'number' && Number.isFinite(v);

function mean(xs) {
  let s = 0;
  for (const x of xs) s += x;
  return s / xs.length;
}

function std(xs) {
  const m = mean(xs);
  let s = 0;
  for (const x of xs) s += (x - m) * (x - m);
  return Math.sqrt(s / xs.length);
}

function slope(idx, ys) {
  const n = ys.length;
  if (n < 2) return 0;
  const mx = mean(idx);
  const my = mean(ys);
  let num = 0;
  let den = 0;
  for (let i = 0; i < n; i += 1) {
    const dx = idx[i] - mx;
    num += dx * (ys[i] - my);
    den += dx * dx;
  }
  return den === 0 ? 0 : num / den;
}

/**
 * @param {Array<{ear?:number, perclos?:number, heartRate?:number, faceConfidence?:number, fusionScore:number}>} window oldest first
 * @param {{earThreshold:number, perclosThreshold:number}} thresholds resolved personal thresholds
 * @returns {number[]} features in FEATURE_NAMES order
 */
function computeFeatures(window, thresholds) {
  const w = window.slice(-WINDOW);
  const n = w.length;
  const earThr = thresholds.earThreshold;
  const perclosThr = thresholds.perclosThreshold;

  const earIdx = [];
  const earRel = [];
  const below = [];
  const perclosIdx = [];
  const perclosRel = [];
  const hrIdx = [];
  const hr = [];
  const face = [];
  const fusion = [];
  let nonalert = 0;
  let drowsy = 0;

  w.forEach((tick, i) => {
    const e = tick.ear;
    if (valid(e)) {
      earIdx.push(i);
      earRel.push(e / earThr);
      below.push(e < earThr);
    } else {
      below.push(false);
    }
    const p = tick.perclos;
    if (valid(p)) {
      perclosIdx.push(i);
      perclosRel.push(p / perclosThr);
    }
    const h = tick.heartRate;
    if (valid(h) && h > 0) {
      hrIdx.push(i);
      hr.push(h);
    }
    const f = tick.faceConfidence;
    face.push(valid(f) ? f : 0);
    const fs = tick.fusionScore || 0;
    fusion.push(fs);
    if (fs > 0.4) nonalert += 1;
    if (fs > 0.7) drowsy += 1;
  });

  let runNow = 0;
  for (let i = below.length - 1; i >= 0 && below[i]; i -= 1) runNow += 1;
  let longest = 0;
  let cur = 0;
  for (const flag of below) {
    cur = flag ? cur + 1 : 0;
    longest = Math.max(longest, cur);
  }

  let earFeats;
  if (earRel.length) {
    const diffs = [];
    for (let i = 1; i < earRel.length; i += 1) diffs.push(Math.abs(earRel[i] - earRel[i - 1]));
    earFeats = [
      earRel[earRel.length - 1],
      mean(earRel),
      Math.min(...earRel),
      std(earRel),
      slope(earIdx, earRel),
      diffs.length ? mean(diffs) : 0,
      below.filter(Boolean).length / n,
    ];
  } else {
    earFeats = [1, 1, 1, 0, 0, 0, 0];
  }

  return [
    n,
    ...earFeats,
    runNow,
    longest,
    n ? (n - earRel.length) / n : 1,
    perclosRel.length ? perclosRel[perclosRel.length - 1] : 0,
    slope(perclosIdx, perclosRel),
    n ? hr.length / n : 0,
    hr.length ? mean(hr) : 0,
    slope(hrIdx, hr),
    face.length ? mean(face) : 0,
    face.length ? Math.min(...face) : 0,
    fusion.length ? fusion[fusion.length - 1] : 0,
    fusion.length ? mean(fusion) : 0,
    n ? nonalert / n : 0,
    n ? drowsy / n : 0,
  ];
}

module.exports = { computeFeatures, FEATURE_NAMES, WINDOW, MIN_TICKS };
